import { Amplify } from 'aws-amplify';

const OUTPUTS_URL = '/amplify_outputs.json';

/**
 * Load backend client config and register the global Amplify context.
 * The file is generated by `npm run sandbox` / Amplify Hosting into frontend/public/.
 */
export async function configureAmplify(): Promise<void> {
  let response: Response;
  try {
    response = await fetch(OUTPUTS_URL, { cache: 'no-store' });
  } catch {
    throw new Error(
      `Could not load ${OUTPUTS_URL}. Run "npm run sandbox" from the repo root to generate frontend/public/amplify_outputs.json.`,
    );
  }

  if (!response.ok) {
    throw new Error(
      `Missing ${OUTPUTS_URL} (HTTP ${response.status}). ` +
        `Amplify Auth cannot work until this file exists. ` +
        `From the repo root run: npm run sandbox`,
    );
  }

  const outputs: unknown = await response.json();
  if (!outputs || typeof outputs !== 'object' || !('version' in outputs)) {
    throw new Error(
      `${OUTPUTS_URL} is not a valid Amplify outputs file. Regenerate it with "npm run sandbox".`,
    );
  }

  Amplify.configure(outputs as Record<string, unknown>);
}
